function sanitize(val) {
  if (val === null || val === undefined) return '';
  return String(val)
    .replace(/'/g,  '')
    .replace(/\\/g, '')
    .replace(/[\x00-\x1F\x7F]/g, '')
    .trim()
    .slice(0, 255);
}

const item           = $input.first().json;
const webhookData    = $('Normalizador WAHA').first().json?.body?.data  || {};
const webhookBody    = $('Normalizador WAHA').first().json?.body        || {};

function normalizeJid(raw) {
  if (!raw) return '';
  let jid = String(raw).trim();
  jid = jid.replace(/:\d+@s\.whatsapp\.net$/, '@s.whatsapp.net');
  jid = jid.replace(/@c\.us$/, '@s.whatsapp.net');
  return jid;
}

const lid            = normalizeJid(item.lid            || '');
