const identity_status = item.identity_status || 'resolved_direct';

// Validar formatos
const lidOk  = lid  === '' || /^\d{5,20}@lid$/.test(lid);
const numOk  = selectedNumber === '' || /^\d{5,20}@s\.whatsapp\.net$/.test(selectedNumber);

const safeLid    = lidOk  ? sanitize(lid)            : '';
const safeNum    = numOk  ? sanitize(selectedNumber) : '';

const pushName    = sanitize(webhookData?.pushName   || '');
const instance    = sanitize(webhookBody?.instance   || '');
const lastEventId = sanitize(webhookData?.key?.id    || '');

return [{
  json: {
    selectedNumber:  safeNum,
    identity_status: identity_status,
    lid:             safeLid,
