const lidRaw = lid.split('@')[0];
const lidNumberValid = /^\d{5,20}$/.test(lidRaw);
const safeLidNumber  = lidNumberValid ? lidRaw : '';
const safeLid        = lidNumberValid ? lid    : '';

const rawPushName = $input.first().json?.body?.data?.pushName || '';
const safePushName = String(rawPushName)
  .replace(/'/g,  '')
  .replace(/\\/g, '')
  .replace(/[\x00-\x1F\x7F]/g, '')
  .trim()
  .slice(0, 255);

return [{ json: {
