// Normalizador WAHA -> Evolution
// Detecta WAHA: body.session + body.payload presentes
// Dedupe: descarta message.any (duplicata de message para incoming)
const raw = $input.first().json;
const b   = raw?.body || {};

// Nao e WAHA - passthrough Evolution sem alteracao
if (!b.session && !b.payload) {
  return [$input.first()];
}

const fromMe = (b.payload || {}).fromMe === true;

// WAHA: remap campos para formato Evolution
const payload = b.payload || {};
const _data   = payload._data  || {};
const info    = _data.Info     || {};

if (info.IsGroup === true || String(info.Chat || '').endsWith('@g.us') || String(payload.from || '').endsWith('@g.us')) {
  return [];
}

function normalizeJid(raw) {
  if (!raw) return '';
  let jid = String(raw).trim();
  jid = jid.replace(/:\d+@s\.whatsapp\.net$/, '@s.whatsapp.net');
  jid = jid.replace(/@c\.us$/, '@s.whatsapp.net');
  return jid;
}

const senderAlt    = normalizeJid(info.SenderAlt    || '');
const recipientAlt = normalizeJid(info.RecipientAlt || '');
const chat         = normalizeJid(info.Chat         || payload.from || '');
const msgText      = payload.body || '';

const primaryAlt    = fromMe ? recipientAlt : senderAlt;
const remoteJid     = primaryAlt || chat;
const remoteJidAlt  = (primaryAlt && chat && primaryAlt !== chat) ? chat : '';
const ts = info.Timestamp || payload.timestamp || 0;

const hasMedia  = payload.hasMedia === true;
const media     = payload.media || {};
const mediaType = info.Type || '';
const mediaUrl  = media.url || '';
const mediaB64  = media.base64 || media.data || '';

let audioMessage  = null;
let imageMessage  = null;
let messageBase64 = '';

if (hasMedia) {
  if (mediaType === 'audio' || mediaType === 'ptt') {
    audioMessage  = { url: mediaUrl, mimetype: media.mimetype || '' };
    messageBase64 = mediaB64;
  } else if (mediaType === 'image') {
    imageMessage  = { url: mediaUrl, mimetype: media.mimetype || '', caption: msgText || '' };
    messageBase64 = mediaB64;
  }
}

return [{
  json: {
    body: {
      instance: b.session || '',
      event:    b.event   || '',
      data: {
        key: {
          remoteJid:    remoteJid,
          remoteJidAlt: remoteJidAlt,
          fromMe:       fromMe,
          id:           payload.id || '',
        },
        source:           payload.source || '',
        pushName:         info.PushName || '',
        messageType:      info.Type     || '',
        messageTimestamp: ts,
        message: {
          conversation:        msgText || '',
          extendedTextMessage: msgText ? { text: msgText } : null,
          audioMessage:        audioMessage,
          imageMessage:        imageMessage,
          base64:              messageBase64,
        },
        contextInfo: {}
      }
    }
  }
}];

